#define CHECK(x) do{auto s=(x);if(s!=cudaSuccess){fprintf(stderr,"CUDA:%s\n",cudaGetErrorString(s));exit(2);}}while(0)
template<typename T>struct Buf{T*base;T*p;int n,g;T sentinel;Buf(int n,int g,T sentinel):n(n),g(g),sentinel(sentinel){CHECK(cudaMalloc(&base,(n+2*g)*sizeof(T)));p=base+g;std::vector<T>x(n+2*g,sentinel);CHECK(cudaMemcpy(base,x.data(),x.size()*sizeof(T),cudaMemcpyHostToDevice));}~Buf(){cudaFree(base);}std::vector<T>get(){std::vector<T>x(n);CHECK(cudaMemcpy(x.data(),p,n*sizeof(T),cudaMemcpyDeviceToHost));return x;}void guards(std::vector<double>&v){std::vector<T>x(n+2*g);CHECK(cudaMemcpy(x.data(),base,x.size()*sizeof(T),cudaMemcpyDeviceToHost));for(int j=0;j<g;j++){if(memcmp(&x[j],&sentinel,sizeof(T)))exit(4);append(v,x[j]);}for(int j=n+g;j<n+2*g;j++){if(memcmp(&x[j],&sentinel,sizeof(T)))exit(4);append(v,x[j]);}}static void append(std::vector<double>&v,float x){v.push_back(x);}static void append(std::vector<double>&v,half x){uint16_t b;memcpy(&b,&x,2);v.push_back(b);}};
struct Case{int id;std::vector<uint16_t>input;std::vector<double>oracle;Buf<half>a{65536,32,half(65504.f)},b{65536,32,half(65504.f)},hr{1,32,half(65504.f)};Buf<float>out{1,16,-8192.f};Case(int id):id(id){std::string root="/home/imo/HeCBench_julia/src/f16sp-julia/";input.resize(131072);std::ifstream f(root+"study_case"+std::to_string(id)+"_u16.bin",std::ios::binary);f.read((char*)input.data(),input.size()*2);oracle.resize(17);std::ifstream e(root+"oracle_case"+std::to_string(id)+"_f64.bin",std::ios::binary);e.read((char*)oracle.data(),17*8);if(!f||!e)exit(3);CHECK(cudaMemcpy(a.p,input.data(),65536*2,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(b.p,input.data()+65536,65536*2,cudaMemcpyHostToDevice));}bool input_check(std::vector<double>*prefix=nullptr){auto av=a.get(),bv=b.get();bool ok=memcmp(av.data(),input.data(),65536*2)==0&&memcmp(bv.data(),input.data()+65536,65536*2)==0;if(prefix)for(auto x:input)prefix->push_back(x);return ok;}void execute(int mode,int grid,void*h){if(mode<=3){CHECK(cudaMemset(out.p,0,4));if(mode==1)scalarProductKernel_intrinsics<<<grid,128>>>((half2*)a.p,(half2*)b.p,out.p,32768);if(mode==2)scalarProductKernel_native_fp32<<<grid,128>>>((half2*)a.p,(half2*)b.p,out.p,32768);if(mode==3)scalarProductKernel_native2_fp32<<<grid,128>>>((half2*)a.p,(half2*)b.p,out.p,32768);CHECK(cudaGetLastError());}else if(mode==4){if(study_cublas(h,a.p,b.p,hr.p,65536))exit(5);}else if(study_cub(a.p,b.p,out.p,32768))exit(6);}void guards(std::vector<double>&g){a.guards(g);b.guards(g);hr.guards(g);out.guards(g);}};
int main(){void*h=nullptr;if(study_create(&h))return 5;printf("VENDOR_PROVENANCE {\"cublas_version\":%d,\"cublas_path\":\"%s\",\"native_runtime_version\":",study_cublas_version(h),study_cublas_path());int runtime=-1;cudaRuntimeGetVersion(&runtime);printf("%d}\n",runtime);Case a(1),b(2);std::vector<std::pair<int,int>>cases;for(int grid:{256,128,64,32,16})for(int mode:{1,2,3})cases.push_back({mode,grid});cases.push_back({4,0});cases.push_back({5,0});for(auto c:{&a,&b})for(auto mg:cases){c->execute(mg.first,mg.second,h);CHECK(cudaDeviceSynchronize());}bool all=true;for(int trial=1;trial<=5;trial++){std::vector<double>prefix,outputs,guards,times;double ma=0,mr=0,scaled=0;bool ok=true;for(auto c:{&a,&b}){ok&=c->input_check(&prefix);double params[]={double(c->id),32768,65536,3,128,256,128,64,32,16,17,1};prefix.insert(prefix.end(),params,params+12);int k=0;for(auto mg:cases){CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int repeat=0;repeat<3;repeat++)c->execute(mg.first,mg.second,h);CHECK(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3);double value=mg.first==4?double(float(c->hr.get()[0])):double(c->out.get()[0]);outputs.push_back(value);c->guards(guards);double e=std::abs(value-c->oracle[k]);ma=std::max(ma,e);mr=std::max(mr,e/std::max(std::abs(c->oracle[k]),2.220446049250313e-16));scaled=std::max(scaled,e/(.02+2e-6*std::abs(c->oracle[k])));ok&=std::isfinite(value)&&e<=.02+2e-6*std::abs(c->oracle[k]);if(mg.first==4)ok&=value==c->oracle[k];k++;}ok&=c->input_check();}all&=ok;auto artifact=prefix;artifact.insert(artifact.end(),outputs.begin(),outputs.end());artifact.insert(artifact.end(),guards.begin(),guards.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)artifact.data(),artifact.size()*8);f.close();double total=0;for(auto t:times)total+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":7650,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"relative_error_floor\":2.220446049250313e-16,\"max_scaled_oracle_error\":%.12g,\"timing_region\":\"sum_two_fixtures_all17_mixed_precision_custom_reset_and_vendor_API_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"timed_cases\":34,\"component_time_seconds\":[",trial,total,ok?"true":"false",ma,mr,scaled);for(size_t i=0;i<times.size();i++){if(i)printf(",");printf("%.12g",times[i]);}printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),artifact.size());}study_destroy(h);return all?0:1;}
